-- Core staff, exams, timetable, notices and payroll operations.
create table public.staff (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools on delete cascade, employee_code text not null, first_name text not null, last_name text, designation text, department text, email text, phone text, date_of_birth date, joining_date date, photo_url text, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(school_id,employee_code));
create table public.leave_types (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools on delete cascade, name text not null, days_per_year numeric(6,2), is_paid boolean not null default true, unique(school_id,name));
create table public.staff_leaves (id uuid primary key default gen_random_uuid(), staff_id uuid not null references public.staff on delete cascade, leave_type_id uuid references public.leave_types, start_date date not null, end_date date not null, reason text, status text not null default 'pending', approved_by uuid references public.profiles, created_at timestamptz not null default now(), check(end_date>=start_date));
create table public.exams (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools on delete cascade, academic_session_id uuid not null references public.academic_sessions on delete cascade, name text not null, exam_type text, start_date date, end_date date, created_at timestamptz not null default now(), unique(school_id,academic_session_id,name));
create table public.exam_schedules (id uuid primary key default gen_random_uuid(), exam_id uuid not null references public.exams on delete cascade, class_id uuid not null references public.classes, subject_id uuid not null references public.subjects, exam_date date not null, start_time time, end_time time, room text, max_marks numeric(8,2), pass_marks numeric(8,2), unique(exam_id,class_id,subject_id));
create table public.exam_marks (id uuid primary key default gen_random_uuid(), exam_schedule_id uuid not null references public.exam_schedules on delete cascade, student_id uuid not null references public.students on delete cascade, marks numeric(8,2), grade text, remarks text, entered_by uuid references public.profiles, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(exam_schedule_id,student_id));
create table public.timetable_periods (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools on delete cascade, name text not null, period_number integer not null, start_time time not null, end_time time not null, unique(school_id,period_number));
create table public.timetables (id uuid primary key default gen_random_uuid(), academic_session_id uuid not null references public.academic_sessions on delete cascade, class_id uuid not null references public.classes, section_id uuid references public.sections, weekday integer not null check(weekday between 1 and 7), period_id uuid not null references public.timetable_periods, subject_id uuid references public.subjects, teacher_id uuid references public.staff, room text, unique(class_id,section_id,weekday,period_id));
create table public.notices (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools on delete cascade, title text not null, body text not null, audience text[] not null default array['all'], published_at timestamptz, expires_at timestamptz, created_by uuid references public.profiles, created_at timestamptz not null default now());
create index idx_staff_school on public.staff(school_id); create index idx_exams_session on public.exams(academic_session_id); create index idx_exam_marks_student on public.exam_marks(student_id); create index idx_timetable_class on public.timetables(class_id,weekday); create index idx_notices_school_date on public.notices(school_id,published_at desc);
alter table public.staff enable row level security; alter table public.leave_types enable row level security; alter table public.staff_leaves enable row level security; alter table public.exams enable row level security; alter table public.exam_schedules enable row level security; alter table public.exam_marks enable row level security; alter table public.timetable_periods enable row level security; alter table public.timetables enable row level security; alter table public.notices enable row level security;
create policy "school members read staff" on public.staff for select to authenticated using(public.has_school_role(school_id,array['super_admin','school_admin','principal','vice_principal','teacher','accountant','hr_manager','staff']::public.app_role[]));
create policy "school managers write staff" on public.staff for all to authenticated using(public.has_school_role(school_id,array['super_admin','school_admin','principal','hr_manager']::public.app_role[])) with check(public.has_school_role(school_id,array['super_admin','school_admin','principal','hr_manager']::public.app_role[]));
create policy "school members read leave types" on public.leave_types for select to authenticated using(public.has_school_role(school_id,array['super_admin','school_admin','principal','teacher','hr_manager','staff']::public.app_role[]));
create policy "school members read exams" on public.exams for select to authenticated using(public.has_school_role(school_id,array['super_admin','school_admin','principal','vice_principal','teacher','parent','student']::public.app_role[]));
create policy "academic leaders write exams" on public.exams for all to authenticated using(public.has_school_role(school_id,array['super_admin','school_admin','principal','vice_principal','teacher']::public.app_role[])) with check(public.has_school_role(school_id,array['super_admin','school_admin','principal','vice_principal','teacher']::public.app_role[]));
create policy "school members read periods" on public.timetable_periods for select to authenticated using(public.has_school_role(school_id,array['super_admin','school_admin','principal','vice_principal','teacher','parent','student']::public.app_role[]));
create policy "school members read notices" on public.notices for select to authenticated using(public.has_school_role(school_id,array['super_admin','school_admin','principal','vice_principal','teacher','accountant','hr_manager','staff','parent','student']::public.app_role[]));
create policy "school leaders write notices" on public.notices for all to authenticated using(public.has_school_role(school_id,array['super_admin','school_admin','principal','vice_principal']::public.app_role[])) with check(public.has_school_role(school_id,array['super_admin','school_admin','principal','vice_principal']::public.app_role[]));
create policy "authenticated read exam schedules" on public.exam_schedules for select to authenticated using(exists(select 1 from public.exams e where e.id=exam_id and public.has_school_role(e.school_id,array['super_admin','school_admin','principal','vice_principal','teacher','parent','student']::public.app_role[])));
create policy "teachers manage exam marks" on public.exam_marks for all to authenticated using(exists(select 1 from public.exam_schedules es join public.exams e on e.id=es.exam_id where es.id=exam_schedule_id and public.has_school_role(e.school_id,array['super_admin','school_admin','principal','vice_principal','teacher']::public.app_role[]))) with check(exists(select 1 from public.exam_schedules es join public.exams e on e.id=es.exam_id where es.id=exam_schedule_id and public.has_school_role(e.school_id,array['super_admin','school_admin','principal','vice_principal','teacher']::public.app_role[])));
